const b = $input.first().json.body || {};
const subject = (b.menuFileName ? b.menuFileName + ' - ' : '') + 'Menu Images';
const matched = b.matchedCount ?? '?';
const missing = b.missingCount ?? '?';
const restaurant = b.restaurantName || 'the restaurant';
const text = `Menu images for ${restaurant}.\n\nMatched: ${matched}\nStill missing: ${missing}\n\n${b.notes || ''}`.trim();
return [{ json: { subject, text, senderEmail: b.senderEmail || '' } }];

const d = $input.first().json;
if (d && d.error) {
  const msg = typeof d.error === 'string' ? d.error : (d.error.message || JSON.stringify(d.error));
  return [{ json: { ok: false, error: String(msg) } }];
}
return [{ json: { ok: true } }];
